-- +goose Up
-- A user is a person who can log in. A profile is a role that person plays in the
-- system. One user can be a customer, a restaurant owner and a driver at once.
CREATE TYPE profile_role AS ENUM ('customer', 'restaurant', 'driver');

CREATE TABLE users (
    -- UUIDv7, generated by the application: unguessable, but time-ordered, so new
    -- rows land at the end of the primary key index instead of at random places.
    id            uuid PRIMARY KEY,
    -- citext compares case-insensitively, so Ali@x.com and ali@x.com collide.
    email         citext NOT NULL UNIQUE,
    password_hash text NOT NULL,
    full_name     text NOT NULL CHECK (length(full_name) BETWEEN 1 AND 100),
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE profiles (
    id         uuid PRIMARY KEY,
    user_id    uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role       profile_role NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    -- At most one profile per role per user. The unique index this creates also
    -- serves "all profiles of this user", since user_id is its first column.
    UNIQUE (user_id, role)
);

-- +goose Down
DROP TABLE profiles;
DROP TABLE users;
DROP TYPE profile_role;
